// js/sources/tasker/actionCodes.js — Tasker action/event/state code table.
//
// Single source of truth: data/taskerCodes.json (GENERATED by
// scripts/gen_tasker_codes.py). This module only *loads* it — there is no
// hand-written second table (a hand-written one was wrong for 9/14 codes).
//
// The codeName is presentation/identity only. Tasker `<code>` values are
// never routed on for plugins: identity lives in arg1 (package) + arg2
// (config activity class).

/** Absolute URL of the generated code tables, resolved relative to this module. */
export const CODES_URL = new URL('../../../data/taskerCodes.json', import.meta.url).href;

/** Families that carry a numeric code table. */
export const CODE_FAMILIES = Object.freeze(['actions', 'events', 'states']);

/**
 * Lookup wrapper around the generated taskerCodes.json.
 *
 * Shape of the JSON (see data/taskerCodes.json):
 *   { actions: {NAME: code}, events: {...}, states: {...},
 *     byCode: { actions: {"<code>": NAME}, events: {...}, states: {...} },
 *     specials: { actions: {NONE, FIRST_PLUGIN_CODE}, ... } }
 */
export class CodeTable {
  /** @param {object} [data] parsed taskerCodes.json (or {} for an empty table) */
  constructor(data = {}) {
    const root = data && typeof data === 'object' ? data : {};
    const byCode = root.byCode && typeof root.byCode === 'object' ? root.byCode : {};
    const specials = root.specials && typeof root.specials === 'object' ? root.specials : {};
    this.data = root;
    this.actions = root.actions || {};
    this.events = root.events || {};
    this.states = root.states || {};
    this.by = {
      actions: byCode.actions || {},
      events: byCode.events || {},
      states: byCode.states || {},
    };
    this.firstPlugin = {
      actions: specials.actions ? specials.actions.FIRST_PLUGIN_CODE : undefined,
      events: specials.events ? specials.events.FIRST_PLUGIN_CODE : undefined,
      states: specials.states ? specials.states.FIRST_PLUGIN_CODE : undefined,
    };
  }

  /**
   * Resolve a numeric code to its published name.
   * Mirrors CodeTable.lookup() in scripts/tasker_xml_ir.py.
   *
   * @param {string} family "actions" | "event" | "state" | "time" | "day" | ...
   * @param {number|null} code
   * @returns {string|null}
   */
  lookup(family, code) {
    const key = family === 'event' ? 'events' : family === 'state' ? 'states' : family;
    const table = this.by[key];
    if (!table || code === null || code === undefined) return null;
    const name = table[String(code)];
    return name === undefined ? null : name;
  }

  /** @param {string} family @returns {number} FIRST_PLUGIN_CODE or 1000 */
  firstPluginCode(family) {
    const v = this.firstPlugin[family];
    return typeof v === 'number' && v !== 0 ? v : 1000;
  }
}

/** Convenience factory for tests / callers that already have the JSON. */
export function makeCodeTable(data) {
  return new CodeTable(data);
}

/**
 * Fetch and wrap data/taskerCodes.json.
 *
 * Browser-only by default (fetch). Tests inject a `tables` object into the
 * parser instead, so they never touch the network.
 *
 * @param {string} [url]
 * @param {typeof fetch} [fetchImpl]
 * @returns {Promise<CodeTable>}
 */
export async function loadCodeTables(url = CODES_URL, fetchImpl) {
  const doFetch = fetchImpl || (typeof fetch === 'function' ? fetch.bind(globalThis) : null);
  if (!doFetch) throw new Error('fetch is unavailable; pass a tables object to the parser');
  const res = await doFetch(url);
  if (!res || !res.ok) throw new Error(`failed to load Tasker code tables from ${url} (HTTP ${res ? res.status : '?'})`);
  return new CodeTable(await res.json());
}

/** Empty table — every code resolves to unknown. Useful for degraded offline mode. */
export const EMPTY_CODE_TABLE = new CodeTable({});

/**
 * Resolve a code table from anything the caller may have: an existing
 * CodeTable, a raw parsed taskerCodes.json object (tests), or a fetch URL.
 *
 * @param {CodeTable|object|string} [source]
 * @returns {Promise<CodeTable>}
 */
export async function loadActionCodes(source) {
  if (source instanceof CodeTable) return source;
  if (source && typeof source === 'object') return new CodeTable(source);
  return loadCodeTables(typeof source === 'string' ? source : CODES_URL);
}
